<script setup lang="ts">
import { SectionDivider } from '@shared/ui'

interface LorItem {
  title: string;
  content: string;
  img: string;
}

const lorImages = import.meta.glob<{ default: string }>('@shared/assets/images/lor/*.webp', { eager: true })
const images = Object.values(lorImages).map(m => m.default)

const lorSections: LorItem[] = [
  { title: '26 АПРЕЛЯ 1986 ГОДА', img: images[0] || '', content: '26 апреля 1986 года в 1 час 23 минуты произошла крупнейшая техногенная катастрофа в мире…\nВ ходе проведения проектного испытания на 4 энергоблоке Чернобыльской Атомной Электростанции произошел гидротермический взрыв. Разрушение носило взрывной характер, реактор был полностью разрушен, а в окружающую среду выброшено большое количество радиоактивных веществ. Авария расценивается как крупнейшая в своём роде за всю историю атомной энергетики. В течение первых трех месяцев после аварии скончался 31 человек, еще 19 смертей с 1987 по 2004 год предположительно можно отнести к ее прямым последствиям. 134 человека из числа ликвидаторов перенесли острую лучевую болезнь. Тем не менее эти цифры существенно меньше того количества жертв, которое приписывается Чернобыльской катастрофе общественным мнением. Территорию вокруг станции огородили 30 километровым забором и назвали ‘’Чернобыльская Зона Отчуждения’’.' },
  { title: '1993 ГОД:', img: images[1] || '', content: 'Когда территория стала закрытой, а гражданское население вывезено за пределы периметра, территория была превращена, в полигон для испытаний и исследований. Был разработан проект “Х” включающий в себя комплекс лабораторий на территории крупных НИИ и заводов. Решением верховного пленума ЦК КПСС было принято использовать вырабатываемую энергию трех энергоблоков для обеспечения комплекса специальных лабораторий. Проектами руководили научные группы которые пытались выявить влияние радиации на биологическую оболочку человека / животных / растений. В этих лабораториях также велось изучение информационной оболочки, предполагаемо окружающей всю планету и содержащей информацию о всех живых существах, включая их чувства, мысли и эмоции.' },
  { title: '10 ИЮНЯ 2006 ГОДА:', img: images[2] || '', content: 'Один из экспериментов выходит из под контроля. При попытке подключения к информационной оболочке земли - аномальная энергия хлынула на поверхность планеты. Зона Отчуждения осветилась нестерпимо ярким светом, на несколько мгновений установилась тишина, и было видно, как в небе испаряются облака. Потом пришёл страшный грохот, содрогнулась земля. Энергия практически беспрепятственно полилась на Землю, изменяя физические законы. Уже через сутки правительственные войска Украины полностью оцепили Зону по периметру, однако внутри периметра осталось еще много людей. Спасательные операции не представлялись возможными из-за высокой аномальной активности. Причина катастрофы так и не установлена. Погибших и пропавших без вести людей всё больше. При попытке подключения к информационной оболочке земли, в небо было выброшено колоссальное количество энергии.\n\nЭто был первый выброс который ознаменовал существование “ЗОНЫ”.' },
  { title: 'ОСЕНЬ 2009 ГОДА:', img: images[3] || '', content: 'В желтой прессе и по слухам военных охраняющих периметр, все чаще стали мелькать заголовки о неизвестных видоизмененных животных, которые пытаются прорваться за территорию ЧЗО на большую землю.' },
  { title: 'ДЕКАБРЬ 2009 ГОДА:', img: images[4] || '', content: 'Зона продолжает расти, точная причина катастрофы так и не была установлена, а погибших или пропавших людей с каждым днём всё больше. Немногочисленные научные экспедиции кончаются неудачами. Тем же временем, появляются неучтенные гражданские лица на территории Зоны. Кто то скрывается от закона, либо занимается мародерством, ища чем поживиться. Рискуя своей жизнью, их конечной целью является поиск и последующая продажа аномальных образований, за которые можно выручить солидные деньги, сбор различного хлама называемого ими хабаром, либо трофейная охота на необычную живность.' },
  { title: 'ВЕСНА 2011 ГОДА', img: images[5] || '', content: 'Зона находится в относительно спокойном состоянии. На территории Зоны Отчуждения находится от 1 до 250 неучтенных лиц. Многие организовали группы, которые придерживаются личных интересов. Одни выступают за её использование государственными структурами, и полного уничтожения. Другие же стремятся познать Зону, открыть её для всего остального мира и сохранить ее как территорию, не обремененную правительствами или какими-либо законами.. Охрана периметра Зоны негласно продает желающим фиктивные лицензии на право нахождения в Зоне, для одних это шанс заработать, для других билет в один конец.' },
  { title: '2012 ГОД:', img: images[6] || '', content: 'Зона обостряет борьбу за выживание, а те, кто ищет ответы или ресурсы, сталкиваются с теми, кто будет готов идти по головам ради своих целей. Зона продолжает расти, поглощая новые территории. Теперь она стала совершенно непредсказуемым и смертельно опасным местом, из которого выходят лишь немногие, а те, кто вернутся, либо теряются навсегда, либо становятся одержимыми ужасными видениями и сверхъестественными явлениями. Зона, как никогда, полна загадок, это уже не просто место, а символ человеческой борьбы с неизвестным, с самим собой и с неизбежными последствиями своих выборов…' },
  { title: 'ИЮНЬ 2012 ГОДА:', img: images[7] || '', content: 'Сидор сидел у себя в подвале, поджав ноги к груди и глядя в одну точку. Лишь звуки потрескивающего огня и мерцающий свет лампы нарушали тишину. Зона… она не переставала меняться. Но теперь все было иначе.\n\nМонолит долго укреплял свои силы на территории зоны, расставляя пси-вышки и одурманивая обитателей, эта безумная фанатичная сила, что обрушилась на бар, казалось, окончательно подавила все, что держало этот уголок мира в относительном порядке. Вооружившись поддержкой разных группировок, Монолит начали захватывать территорию бара, многие группировки, не поддерживающие их идеологию, встали на защиту, но силы были неравны... Монолит смогли захватить территорию бара.' },
  { title: '2013 ГОД.', img: images[8] || '', content: 'Прошел год с тех пор, как последний сталкер покинул Чернобыльскую зону, и она, наконец, вернулась к своему первоначальному состоянию. Дикая природа вновь захватила территорию. Но вместе с этим начали появляться новые угрозы — неожиданные аномалии, более смертоносные существа и тайные группировки, что затмило весь прежний порядок. Беглецы, решившие вернуться, сталкиваются с опасностью, которой еще не видели. Мистика и хаос вновь охватывают зону, и лишь немногие решаются вновь ступить на ее земли, готовые искать ответы на вопросы, оставшиеся без ответа.' },
  { title: 'ЗИМА 2013 ГОД', img: images[9] || '', content: 'Зона оказалась укутана белоснежным снегом, но, несмотря на кажущееся спокойствие, она оставалась такой же тёмной и смертельно опасной. Всё чаще вдоль дорог можно было увидеть догорающие костры, сталкеры готовились к праздникам, украшая редкие, голые ёлки старыми новогодними игрушками. Даже в эти редкие моменты тепла и радости фанатики не теряли бдительности, делая всё возможное, чтобы вытеснить людей со своих земель.\n\nВ один из особенно морозных зимних дней бармен сообщил ужасающую новость: "Монолит добрался до территории бара". Все группировки и одиночки объединились, чтобы дать отпор врагу, но их силы оказались неравны. В итоге бойцы Монолита захватили земли ЧЗО, оставив после себя лишь страх и разруху.' },
  { title: 'НАСТОЯЩЕЕ ВРЕМЯ', img: images[10] || '', content: 'Прошло несколько месяцев с тех событий, как Монолит установил свою власть над землями ЧЗО, и Зона изменилась до неузнаваемости. Заброшенные лагеря и разрушенные укрытия медленно поглощались снегом и дикой природой, словно людей здесь никогда и не было. Однако вместе с тишиной пришли новые угрозы: аномалии стали непредсказуемее, мутанты - агрессивнее, а в тени появились неизвестные группировки, скрывающиеся от взора фанатиков. Ходили слухи, что влияние Монолита ослабевает, и Зона начинает жить по собственным, искажённым законам. Немногие сталкеры, решившиеся вернуться, сталкивались с опасностями, которых прежде не знали. Мистика и хаос снова охватили Зону, оставляя лишь один вопрос - кто теперь её настоящий хозяин.' }
]
